def cmd_audit_verify(args: argparse.Namespace) -> int:
    """Offline audit export verification; no server contact is made.

    The input is one export page or a JSON array of pages (the pages of a
    full export, in order), read from ``FILE`` or standard input when the
    argument is ``-``. Prints a single JSON line:
    ``{"ok": true, "checkpoint": {...}}`` on success or
    ``{"ok": false, "error": "input"|"integrity"|"auth"}`` on failure, and
    exits 0/1 respectively.

    Without ``--trust`` only the hash chain is checked. With a trust document
    its genesis anchor and ``audit_signers`` additionally authenticate every
    page's ``checkpoint_auth`` signature and bind the pages to one another.
    """
    from .audit import verify_export

    try:
        if args.export_file == "-":
            document = json.loads(sys.stdin.read())
        else:
            with open(args.export_file, "r", encoding="utf-8") as fh:
                document = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON input is an input error.
        body = {"ok": False, "error": "input"}
    else:
        trust = None
        if args.trust is not None:
            try:
                with open(args.trust, "r", encoding="utf-8") as fh:
                    trust = json.load(fh)
            except (OSError, ValueError, UnicodeDecodeError):
                body = {"ok": False, "error": "input"}
                print(json.dumps(body, sort_keys=True, ensure_ascii=False))
                return 1
        body = verify_export(document, trust)
    print(json.dumps(body, sort_keys=True, ensure_ascii=False))
    return 0 if body.get("ok") is True else 1


def cmd_consistency(args: argparse.Namespace) -> int:
    """Offline whole-snapshot consistency verification; no server contact.

    The input is one persisted snapshot document read from ``FILE`` or
    standard input when the argument is ``-``. Prints a single JSON line with
    the fixed key order ``ok,error,generation,height,tip_hash,state_root,
    audit_checkpoint``: success carries the recomputed summary, failure
    carries ``{"ok": false, "error": "input"|"integrity"}`` with every other
    field null. Exits 0 on success, 1 on any failure (including unreadable or
    non-JSON input).
    """
    from .consistency import verify_snapshot

    try:
        if args.snapshot_file == "-":
            document = json.loads(sys.stdin.read())
        else:
            with open(args.snapshot_file, "r", encoding="utf-8") as fh:
                document = json.load(fh)
    except (OSError, ValueError, UnicodeDecodeError):
        # Unreadable or non-JSON input is an input error.
        body = {"ok": False, "error": "input"}
    else:
        body = verify_snapshot(document)
    print(json.dumps(body, sort_keys=False, ensure_ascii=False))
    return 0 if body.get("ok") is True else 1


def _decimal_int(value: str) -> int | None:
    """Parse a decimal CLI integer, or None for anything unparseable.

    Kept manual (rather than an argparse ``type=int``) so a malformed option
    reports the command's JSON ``input`` envelope and exit 1 instead of an
    argparse usage error and exit 2.
    """
    try:
        return int(value, 10)
    except (TypeError, ValueError):
        return None


def _emit_result_document(body: dict) -> int:
    """Print one JSON line preserving the document's contract key order.

    A success is the document itself (a page or a ``{root, records, head}``
    log) with no ``ok`` key; only a failure carries ``{"ok": false,
    "error"}``. Insertion order is kept so declared key orders survive.
    """
    print(json.dumps(body, sort_keys=False, ensure_ascii=False))
    return 1 if body.get("ok") is False else 0


def _input_failure() -> int:
    return _emit_result_document({"ok": False, "error": "input"})


def cmd_history_trust(args: argparse.Namespace) -> int:
    """Read or update the durable checkpoint-history signer log.

    No update options means read; an update requires all four of
    ``--root-key/--at/--key/--status``. Prints the ``{root, records, head}``
    document as one contract-ordered JSON line, exit 0/1 on success/failure.
    """
    from .light_client import history_trust

    options = (args.root_key, args.at, args.key, args.status)
    if not any(option is not None for option in options):
        body = history_trust(args.path)
        return _emit_result_document(body)

    at_value = _decimal_int(args.at) if args.at is not None else None
    if args.at is not None and at_value is None:
        return _input_failure()
    body = history_trust(
        args.path, args.root_key, at_value, args.key, args.status
    )
    return _emit_result_document(body)


def cmd_history_export(args: argparse.Namespace) -> int:
    """Export one signed checkpoint-history page; no server contact is made."""
    from .light_client import HISTORY_EXPORT_DEFAULT_LIMIT, export_history

    after = None
    if args.after is not None:
        after = _decimal_int(args.after)
        if after is None:
            return _input_failure()
    limit = HISTORY_EXPORT_DEFAULT_LIMIT
    if args.limit is not None:
        limit = _decimal_int(args.limit)
        if limit is None:
            return _input_failure()
    body = export_history(
        args.path,
        args.key,
        after=after,
        limit=limit,
        trust_path=args.trust,
    )
    return _emit_result_document(body)


def cmd_header_locators(args: argparse.Namespace) -> int:
    """Build a fork-location locator request from an advance_headers checkpoint.

    No server contact is made: the checkpoint file is strictly reloaded and
    replayed (never rewritten) and the derived ``{"locators", "limit"}``
    request document is printed as one contract-ordered JSON line, ready to
    POST to ``/v1/chain/headers/locate``. Success exits 0; any failure
    prints ``{"ok": false, "error": "input"|"io"|"state"}`` and exits 1.
    """
    from .light_client import HEADER_LOCATORS_DEFAULT_LIMIT, header_locators

    limit = HEADER_LOCATORS_DEFAULT_LIMIT
    if args.limit is not None:
        limit = _decimal_int(args.limit)
        if limit is None:
            return _input_failure()
    body = header_locators(args.path, limit)
    if not body.get("ok"):
        return _emit_result_document(body)
    print(json.dumps(body["request"], sort_keys=False, ensure_ascii=False))
    return 0


